+import { tz } from "@date-fns/tz";
+import { describe, expect, it } from "vitest";
+import { isSameDay } from "../index.js";
+
+describe("isSameDay regressions", () => {
+  it("treats different times on the same local calendar day as equal", () => {
+    expect(
+      isSameDay(
+        new Date(2024, 5, 7, 0, 1),
+        new Date(2024, 5, 7, 23, 59),
+      ),
+    ).toBe(true);
+  });
+
+  it("preserves month and year distinctions", () => {
+    expect(isSameDay(new Date(2024, 5, 7, 9), new Date(2024, 6, 7, 9))).toBe(
+      false,
+    );
+    expect(isSameDay(new Date(2024, 5, 7, 9), new Date(2025, 5, 7, 9))).toBe(
+      false,
+    );
+  });
+
+  it("returns false for invalid dates without mutating date inputs", () => {
+    const validDate = new Date(2024, 5, 7, 12, 30);
+    const invalidDate = new Date(NaN);
+    const validTime = validDate.getTime();
+
+    expect(isSameDay(invalidDate, validDate)).toBe(false);
+    expect(validDate.getTime()).toBe(validTime);
+    expect(invalidDate.getTime()).toBeNaN();
+  });
+
+  it("normalizes string and timestamp inputs in the requested context", () => {
+    const context = tz("America/Los_Angeles");
+    const first = "2024-04-10T07:00:00Z";
+    const second = new Date("2024-04-10T15:00:00Z").getTime();
+
+    expect(isSameDay(first, second, { in: context })).toBe(true);
+  });
+});
